param([string[]]$Shas=@("357f4ed5e84383fa0a42802f69eecec74b9e8e5d","4707cbe95a9f3aba92349c521d695c254740ca8c","45c6bfd630aa89141ba96b63833b5622cd66b8dd","e23d72ab6634ac61957a73924cca2c2dc30e01c9","07a05c42f01ab0ec127bd7a3142301c0611e595a","38ee4a1686cb1915e76a81a793037863fbce1f47","6fce383f5700eb2e6dbd9453a0079be4bd99a6e9",$env:GITHUB_SHA),[string]$Owner="eemntirey",[string]$Repository="MadaSearch",[string]$OutputDirectory=(Join-Path $PSScriptRoot "../../docs/recette/attributs-tests"))
$ErrorActionPreference="Stop";$OutputDirectory=[IO.Path]::GetFullPath($OutputDirectory);New-Item -ItemType Directory -Force -Path $OutputDirectory|Out-Null
$h=@{"Accept"="application/vnd.github+json";"X-GitHub-Api-Version"="2022-11-28";"User-Agent"="MadaSearch-TestAttributeAudit"};if($env:GITHUB_TOKEN){$h.Authorization="Bearer $env:GITHUB_TOKEN"}
function Resolve-Sha([string]$r){(Invoke-RestMethod -Headers $h -Uri "https://api.github.com/repos/$Owner/$Repository/commits/$r").sha}
function Get-Tree([string]$s){$t=Invoke-RestMethod -Headers $h -Uri ("https://api.github.com/repos/$Owner/$Repository/git/trees/"+$s+"?recursive=1");if($t.truncated){throw "Tree tronqué: $s"};@($t.tree|Where-Object {$_.type -eq "blob"})}
function Project-Of([string]$p){if($p -match '^(tests/[^/]+)/'){return $Matches[1]};"(hors projet tests identifié)"}
$rows=[Collections.Generic.List[object]]::new();$snaps=[Collections.Generic.List[object]]::new()
foreach($ref in ($Shas|Where-Object {$_}|Select-Object -Unique)){try{$sha=Resolve-Sha $ref;$files=@((Get-Tree $sha)|Where-Object {$_.path -match '^tests/.+\.cs$'});$snap=[Collections.Generic.List[object]]::new();foreach($f in $files){$txt=(Invoke-WebRequest -Uri "https://raw.githubusercontent.com/$Owner/$Repository/$sha/$($f.path)" -UseBasicParsing).Content;$c=[ordered]@{"[Fact]"=[regex]::Matches($txt,'(?<![\w])\[Fact(?:Attribute)?\s*(?:\([^]]*\))?\]','IgnoreCase').Count;"[Theory]"=[regex]::Matches($txt,'(?<![\w])\[Theory(?:Attribute)?\s*(?:\([^]]*\))?\]','IgnoreCase').Count;"[InlineData]"=[regex]::Matches($txt,'\[InlineData(?:Attribute)?\s*\(','IgnoreCase').Count;"[MemberData]"=[regex]::Matches($txt,'\[MemberData(?:Attribute)?\s*\(','IgnoreCase').Count;"[ClassData]"=[regex]::Matches($txt,'\[ClassData(?:Attribute)?\s*\(','IgnoreCase').Count;"Skip="=[regex]::Matches($txt,'\bSkip\s*=','IgnoreCase').Count};foreach($a in $c.Keys){$rows.Add([pscustomobject]@{sha=$sha;input_sha=$ref;project=(Project-Of $f.path);path=$f.path;blob_sha=$f.sha;attribute=$a;total=$c[$a]})};$snap.Add([pscustomobject]@{path=$f.path;project=(Project-Of $f.path);blob_sha=$f.sha})};$snaps.Add([pscustomobject]@{input_sha=$ref;sha=$sha;files=@($snap)});Write-Host "$ref : $($files.Count) fichiers"}catch{$snaps.Add([pscustomobject]@{input_sha=$ref;sha=$null;files=@();error=$_.Exception.Message});Write-Warning "$ref : $($_.Exception.Message)"}}
$moves=[Collections.Generic.List[object]]::new();$removed=[Collections.Generic.List[object]]::new();for($i=1;$i -lt $snaps.Count;$i++){$a=$snaps[$i-1];$b=$snaps[$i];if(!$a.sha -or !$b.sha){continue};$bb=@{};foreach($f in $b.files){if(!$bb.ContainsKey($f.blob_sha)){$bb[$f.blob_sha]=@()};$bb[$f.blob_sha]+=$f};foreach($f in $a.files){if($bb.ContainsKey($f.blob_sha)){foreach($n in $bb[$f.blob_sha]){if($f.path -ne $n.path -or $f.project -ne $n.project){$moves.Add([pscustomobject]@{from_sha=$a.sha;to_sha=$b.sha;from_path=$f.path;from_project=$f.project;to_path=$n.path;to_project=$n.project;blob_sha=$f.blob_sha;justification="Identité du blob Git conservée."})}}}elseif(-not @($b.files|Where-Object {[IO.Path]::GetFileName($_.path) -eq [IO.Path]::GetFileName($f.path)}).Count){$removed.Add([pscustomobject]@{from_sha=$a.sha;to_sha=$b.sha;path=$f.path;project=$f.project;status="à justifier"})}}}
$totals=foreach($g in ($rows|Group-Object sha,project,attribute)){$x=$g.Group[0];[pscustomobject]@{sha=$x.sha;input_sha=$x.input_sha;project=$x.project;attribute=$x.attribute;total=(($g.Group|Measure-Object total -Sum).Sum)}};$errors=@($snaps|Where-Object {$_.error});$status=if($errors.Count -or $removed.Count){"bloqué — revue requise"}else{"vérifié — aucun candidat de suppression non justifiée détecté"}
$r=[pscustomobject]@{generated_at=[DateTimeOffset]::UtcNow.ToString("o");repository="$Owner/$Repository";method="GitHub REST tree + raw content; comptage statique par projet, distinct d'un TRX.";status=$status;shas=@($snaps|ForEach-Object {[pscustomobject]@{input_sha=$_.input_sha;sha=$_.sha;files=$_.files.Count;error=$_.error}});totals=@($totals);movements=@($moves|Sort-Object from_sha,from_path,to_path -Unique);removal_candidates=@($removed);errors=@($errors|ForEach-Object {[pscustomobject]@{sha=$_.input_sha;error=$_.error}})}
$r|ConvertTo-Json -Depth 12|Set-Content (Join-Path $OutputDirectory "attributs-tests.json") -Encoding utf8
$md=[Collections.Generic.List[string]]::new();$md.Add("# Inventaire xUnit");$md.Add("");$md.Add("- Date UTC : $($r.generated_at)");$md.Add("- Statut : $status");$md.Add("| SHA | Projet | Attribut | Total |");$md.Add("|---|---|---|---:|");foreach($x in ($totals|Sort-Object sha,project,attribute)){$md.Add("| $($x.sha) | $($x.project) | $($x.attribute) | $($x.total) |")};$md.Add("");$md.Add("## Déplacements exacts");foreach($x in ($moves|Sort-Object from_sha,from_path,to_path -Unique)){$md.Add("- $($x.from_sha.Substring(0,7)) → $($x.to_sha.Substring(0,7)): $($x.from_path) → $($x.to_path); blob identique.")};$md.Add("");$md.Add("## Candidats à justifier");foreach($x in $removed){$md.Add("- $($x.path) entre $($x.from_sha.Substring(0,7)) et $($x.to_sha.Substring(0,7))")};$md|Set-Content (Join-Path $OutputDirectory "attributs-tests.md") -Encoding utf8;Write-Host "O1=$status"
